SourceCode.Declaration:
[TFMListELementAttribute('Value')]
class TFMListValueElement extends TFMListBase
{
    TFMListValueIf	valueIf;
    Description255	dataMemberValue;
    TFMFontID		fontId;
    TFMDataSetField	text;
    ResourceName	resName;

}

Method.Source:
[TFMParameter('', "If")]
public TFMListValueIfEnum parmIf(TFMListValueIfEnum _valueIf = valueIf)
{
    valueIf = _valueIf;
    return valueIf;
}

[TFMParameter('', "@TFM:DataMemberValue")]
public Description255 parmDataMemberValue(Description255 _dataMemberValue = dataMemberValue)
{
    dataMemberValue = _dataMemberValue;
    return dataMemberValue;
}

[TFMParameter('','','textElement')]
public TFMFontID parmFontId(TFMFontID _fontID = fontID)
{
    fontID = _fontID;
    return fontID;
}

[TFMParameter('','','textElement')]
public TFMDataSetField parmText(TFMDataSetField _text = text)
{
    text = _text;
    return text;
}

[TFMParameter('','', 'imageElement')]
public ResourceName parmImageId(ResourceName _resName = resName)
{
    resName = _resName;
    return resName;
}

public str attributeSummary()
{
    return 'If ' + strFmt('%1',valueIf) + ' ' + dataMemberValue + ': ' + text;
}

    public void appendToXML(XmlElement _parent, boolean _expandCustomComponents)

    {
        XmlElement	valueElement = _parent.ownerDocument().createElement('value');
		if(resName)
        {
            valueElement.setAttribute('imageId',resName);
        }
		if(text)
        {
            valueElement.setAttribute('text',text);
        }
		if (fontId)
        {
            valueElement.setAttribute('fontId',fontId);
        }
		if(dataMemberValue)
        {
            valueElement.setAttribute('dataMemberValue',dataMemberValue);
        }
        valueElement.setAttribute('if',TFMHelper::enumName(enumNum(TFMListValueIf),valueIf));
        _parent.appendChild(valueElement);
    }
